-- ============================================================
-- topic_quizzes : one MCQ per topic (150 rows)
-- Shown as a quiz card in the footer slot of every topic page
-- (and as a random question card on the home page).
-- Import:  mysql -u root vedic_astrology_learn < seed_topic_quiz.sql
-- ============================================================

USE vedic_astrology_learn;

CREATE TABLE IF NOT EXISTS topic_quizzes (
  id             SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
  topic_id       SMALLINT UNSIGNED NOT NULL,
  question_np    VARCHAR(500) NOT NULL,
  question_en    VARCHAR(500) DEFAULT NULL,
  option_a       VARCHAR(255) NOT NULL,
  option_b       VARCHAR(255) NOT NULL,
  option_c       VARCHAR(255) NOT NULL,
  option_d       VARCHAR(255) NOT NULL,
  correct_option ENUM('a','b','c','d') NOT NULL,
  explanation_np TEXT,
  PRIMARY KEY (id),
  UNIQUE KEY uniq_topic_quizzes_topic (topic_id),
  CONSTRAINT fk_topic_quizzes_topic FOREIGN KEY (topic_id)
    REFERENCES topics (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT IGNORE INTO topic_quizzes
  (topic_id, question_np, question_en, option_a, option_b, option_c, option_d, correct_option, explanation_np)
VALUES
-- ---------- bhava (12) ----------
(1,'लग्न भावले मुख्यतः कसलाई जनाउँछ?','What does the Lagna (1st house) primarily represent?','आर्थिक सम्पत्ति र धन','व्यक्तिको शरीर, रूप र परिचय','सन्तान र बुद्धि','जीवनसाथी र विवाह','b','लग्न भाव व्यक्तिको शरीर, रूप, स्वभाव र व्यक्तित्वको परिचय गराउँछ।'),
(2,'दोस्रो भाव (धन भाव) कुन विषय देखाउँछ?','Which subject does the 2nd house (Dhana) signify?','धन, सम्पत्ति र परिवार','शत्रु र रोग','भाइबहिनी','धर्म र भाग्य','a','दोस्रो भाव व्यक्तिको आर्थिक स्थिति, सम्पत्ति र परिवारको भाव हो।'),
(3,'तेस्रो भाव (सहज भाव) कससम्बन्धी मानिन्छ?','What is the 3rd house (Sahaja) associated with?','विवाह र जीवनसाथी','भाग्य र धर्म','भाइबहिनी र साहस','मोक्ष र त्याग','c','तेस्रो भाव भाइबहिनी, साहस, पराक्रम र छोटो यात्राको भाव हो।'),
(4,'चौथो भाव (सुख भाव) कुनको कारक हो?','What does the 4th house (Sukha) rule?','सुख, घर र भूमि','सन्तान र शिक्षा','पेशा र कर्म','ऋण र शत्रु','a','चौथो भाव सुख, घर-बारी, भूमि, वाहन र माताको भाव हुन्छ।'),
(5,'पाँचौं भाव (पुत्र भाव) कसलाई जनाउँछ?','What does the 5th house (Putra) signify?','शत्रु र ऋण','सन्तान र बुद्धि','भाइबहिनी','खर्च र व्यय','b','पाँचौं भाव सन्तान, शिक्षा, बुद्धि र पूर्वजोग्य (पुण्य) को भाव हो।'),
(6,'छैटौं भाव (रिपु भाव) कससम्बन्धी हुन्छ?','What is the 6th house (Ripu) about?','विवाह र साझेदारी','भाग्य र धर्म','शत्रु, रोग र ऋण','मोक्ष र त्याग','c','छैटौं भाव शत्रु, रोग, ऋण र प्रतिद्वन्द्विताको भाव हो।'),
(7,'सातौं भाव (सुता भाव) कुन विषयको हो?','Which subject belongs to the 7th house (Suta)?','विवाह र जीवनसाथी','सन्तान','साहस र पराक्रम','विदेश यात्रा','a','सातौं भाव विवाह, जीवनसाथी र व्यापारिक साझेदारीको भाव हो।'),
(8,'आउठौं भाव (रन्द्र भाव) कससम्बन्धी मानिन्छ?','What is the 8th house (Randhra) associated with?','शिक्षा र बुद्धि','धन र सम्पत्ति','कर्म र पेशा','आयु र रहस्य','d','आउठौं भाव आयु, रहस्य, अचानक घटना र जीवनको ठूलो परिवर्तनको भाव हो।'),
(9,'नौं भाव (धर्म भाव) कुनको कारक हो?','What does the 9th house (Dharma) rule?','रोग र शत्रु','धर्म, भाग्य र पिता','व्यय र खर्च','साहस र भाइ','b','नौं भाव धर्म, भाग्य, पिता, तीर्थ र उच्च शिक्षाको भाव हो।'),
(10,'दसौं भाव (कर्म भाव) कसलाई देखाउँछ?','What does the 10th house (Karma) show?','कर्म, पेशा र सम्मान','सन्तान र बुद्धि','भाइबहिनी','मोक्ष र त्याग','a','दसौं भाव कर्म, पेशा, सम्मान र सार्वजनिक स्थितिको भाव हो।'),
(11,'एघारौं भाव (लाभ भाव) कुन विषय देखाउँछ?','Which subject does the 11th house (Labha) signify?','खर्च र व्यय','रोग र ऋण','आय र लाभ','विवाह र साझेदारी','c','एघारौं भाव आमदनी, लाभ, इच्छा पूर्ति र मित्रहरूको भाव हो।'),
(12,'बाह्रौं भाव (व्यय भाव) कससम्बन्धी हुन्छ?','What is the 12th house (Vyaya) related to?','आय र लाभ','खर्च, विदेश र व्यय','सन्तान','भाइबहिनी','b','बाह्रौं भाव खर्च, विदेशवास, विश्राम र मुक्तिको भाव हो।'),
